 187	impl From<SumRefusal> for AttemptStop {
 188	    fn from(refusal: SumRefusal) -> Self {
 189	        match refusal {
 190	            SumRefusal::Span => Self::Span,
 191	            SumRefusal::Exponent => Self::Exponent,
 192	            SumRefusal::NonFinite => Self::Arithmetic(WideError::NonFinite),
 193	            SumRefusal::Wide(e) => Self::Arithmetic(e),
 194	        }
 195	    }
 196	}
