 198	impl From<WideError> for AttemptStop {
 199	    fn from(error: WideError) -> Self {
 200	        match error {
 201	            WideError::ExponentRange => Self::Exponent,
 202	            other => Self::Arithmetic(other),
 203	        }
 204	    }
 205	}
