2671	/// One publication algorithm for both the public pure helper and the metered
2672	/// production gate. Shape and finite metadata are checked by the latter's caller.
2673	fn publication_with(
2674	    layout: &[QuantityMeta],
2675	    values: &[Binary64Outcome],
2676	    extents: &[f64],
2677	    floor: Option<&[[f64; 2]]>,
2678	    mut classify_row: impl FnMut(f64, f64) -> Result<RowClass, AttemptStop>,
2679	) -> Result<Publication, AttemptStop> {
2680	    let mut s = vec![[0.0f64; 4]; extents.len()];
2681	    for (meta, v) in layout.iter().zip(values) {
2682	        if meta.input_derived {
2683	            continue;
2684	        }
2685	        if let Some(x) = v.value() {
2686	            let slot = &mut s[meta.body as usize][meta.kind.index()];
2687	            *slot = slot.max(x.abs());
2688	        }
2689	    }
2690	    let scales: Vec<[f64; 4]> = s
2691	        .iter()
2692	        .zip(extents)
2693	        .enumerate()
2694	        .map(|(b, (&s, &e))| {
2695	            let mut c = coupled_scales(s, e);
2696	            if let Some(phi) = floor {
2697	                c[Kind::Force.index()] = c[Kind::Force.index()].max(phi[b][0]);
2698	                c[Kind::Moment.index()] = c[Kind::Moment.index()].max(phi[b][1]);
2699	            }
2700	            c
2701	        })
2702	        .collect();
2703	    let rows = layout
2704	        .iter()
2705	        .zip(values)
2706	        .map(|(meta, v)| {
2707	            let class = if meta.input_derived {
2708	                RowClass::InputDerived
2709	            } else if let Some(x) = v.value() {
2710	                classify_row(x, scales[meta.body as usize][meta.kind.index()])?
2711	            } else {
2712	                RowClass::Unpublishable
2713	            };
2714	            Ok(PublishedRow {
2715	                id: meta.id,
2716	                kind: meta.kind,
2717	                body: meta.body,
2718	                value: *v,
2719	                class,
2720	            })
2721	        })
2722	        .collect::<Result<Vec<_>, AttemptStop>>()?;
2723	    let body_scales = scales
2724	        .iter()
2725	        .enumerate()
2726	        .flat_map(|(b, s)| {
2727	            Kind::ALL
2728	                .iter()
2729	                .map(move |&k| (b as u32, k, s[k.index()].to_bits()))
2730	        })
2731	        .collect();
2732	    Ok(Publication { rows, body_scales })
2733	}
