2743	fn finite_nonnegative(value: f64) -> Result<(), CertificateIssue> {
2744	    if !value.is_finite() {
2745	        Err(CertificateIssue::NonFinite)
2746	    } else if value.to_bits() == 1u64 << 63 {
2747	        Err(CertificateIssue::NonCanonicalZero)
2748	    } else if value < 0.0 {
2749	        Err(CertificateIssue::NegativeField)
2750	    } else {
2751	        Ok(())
2752	    }
2753	}
