2756	fn sum_work_delta(after: SumWork, before: SumWork) -> SumWork {
2757	    SumWork {
2758	        term_limbs: after.term_limbs - before.term_limbs,
2759	        shift_limbs: after.shift_limbs - before.shift_limbs,
2760	        net_limbs: after.net_limbs - before.net_limbs,
2761	        rounded_limbs: after.rounded_limbs - before.rounded_limbs,
2762	        max_span_bits: after.max_span_bits,
2763	    }
