2788	    fn checked<T>(&self, result: Result<T, AttemptStop>) -> Result<T, AttemptStop> {
2789	        // Keep an arithmetic refusal's existing precedence; charge its work in
2790	        // the caller before returning it. Case wins over Invocation in test().
2791	        match result {
2792	            Ok(value) => {
2793	                self.guard.test(self.total())?;
2794	                Ok(value)
2795	            }
2796	            Err(stop) => Err(stop),
2797	        }
2798	    }
