2800	    fn collect<T>(
2801	        &mut self,
2802	        sum: &ExactWideSum,
2803	        result: Result<T, AttemptStop>,
2804	    ) -> Result<T, AttemptStop> {
2805	        self.sums.merge(&sum.work());
2806	        self.checked(result)
2807	    }
