2809	    fn clone_delta<T>(
2810	        &mut self,
2811	        sum: &ExactWideSum,
2812	        before: SumWork,
2813	        result: Result<T, AttemptStop>,
2814	    ) -> Result<T, AttemptStop> {
2815	        self.sums.merge(&sum_work_delta(sum.work(), before));
