2819	    fn reaches(
2820	        &mut self,
2821	        c: f64,
2822	        den: &ExactWideSum,
2823	        num: &ExactWideSum,
2824	    ) -> Result<bool, AttemptStop> {
2825	        let mut scratch = ExactWideSum::new();
2826	        let result = (|| {
2827	            if c != 0.0 {
2828	                let bits = c.to_bits();
2829	                let biased = ((bits >> 52) & 0x7ff) as i64;
2830	                let fraction = bits & ((1u64 << 52) - 1);
2831	                let (significand, lsb) = if biased == 0 {
2832	                    (fraction, -1074)
2833	                } else {
2834	                    (fraction | (1u64 << 52), biased - 1075)
2835	                };
2836	                scratch.add_scaled(den, false, significand, lsb)?;
2837	            }
2838	            scratch.add_scaled(num, true, 1, 0)?;
2839	            Ok(scratch.signum() >= 0)
2840	        })();
2841	        self.collect(&scratch, result)
2842	    }
