2844	    /// Accounting-aware upward H/1 conversion. Same exact correction as
2845	    /// directed_ratio(Up); the old R7 helper and its work contract are unchanged.
2846	    fn round_up(&mut self, num: &ExactWideSum) -> Result<f64, AttemptStop> {
2847	        let mut n = num.clone();
2848	        let before = n.work();
2849	        let sign = n.signum();
2850	        self.clone_delta(
2851	            &n,
2852	            before,
2853	            if sign < 0 {
2854	                Err(certificate_error(None, CertificateIssue::NegativeField))
2855	            } else {
2856	                Ok(())
2857	            },
2858	        )?;
2859	        if sign == 0 {
2860	            return Ok(0.0);
2861	        }
2862	        let before = n.work();
2863	        let nv = n.round(&mut self.ctx).map_err(AttemptStop::from);
2864	        let nv = self.clone_delta(&n, before, nv)?;
2865	        let mut den = ExactWideSum::new();
2866	        let formed = den.add_binary64(1.0, false).map_err(AttemptStop::from);
2867	        self.collect(&den, formed)?;
2868	        let mut d = den.clone();
2869	        let before = d.work();
2870	        let dv = d.round(&mut self.ctx).map_err(AttemptStop::from);
2871	        let dv = self.clone_delta(&d, before, dv)?;
2872	        let quotient = self.ctx.div(&nv, &dv).map_err(AttemptStop::from);
2873	        let quotient = self.checked(quotient)?;
2874	        let mut c = match quotient.to_binary64() {
2875	            Binary64Outcome::Normal(v) => v.abs(),
2876	            Binary64Outcome::Subnormal { value, .. } => value.abs(),
2877	            Binary64Outcome::Underflow { .. } => 0.0,
2878	            Binary64Outcome::Overflow { .. } => f64::MAX,
2879	        };
2880	        while !self.reaches(c, &den, num)? {
2881	            if c == f64::MAX {
2882	                return Ok(f64::INFINITY);
2883	            }
2884	            c = next_up(c);
2885	        }
2886	        while c > 0.0 && self.reaches(next_down(c), &den, num)? {
2887	            c = next_down(c);
2888	        }
2889	        self.checked(Ok(c))
2890	    }
