2892	    fn row_bound(&mut self, value: f64, scale: f64) -> Result<f64, AttemptStop> {
2893	        finite_nonnegative(scale).map_err(|e| certificate_error(None, e))?;
2894	        if !value.is_finite() {
2895	            return Err(certificate_error(None, CertificateIssue::NonFinite));
2896	        }
2897	        let b = absolute_bound(scale);
2898	        if scale == 0.0 || scale >= f64::from_bits(0x0230_0000_0000_0000) {
2899	            return self.checked(Ok(b));
2900	        }
2901	        let q = value.abs();
2902	        let two53 = 9_007_199_254_740_992.0;
2903	        let nearest = q / two53;
2904	        let rounding = if nearest * two53 < q {
2905	            next_up(nearest)
2906	        } else {
2907	            nearest
2908	        };
2909	        let mut num = ExactWideSum::new();
2910	        let formed = (|| {
2911	            num.add_binary64(b, false)?;
2912	            num.add_binary64(rounding, false)?;
2913	            num.add_binary64(f64::from_bits(1), false)?;
2914	            Ok(())
2915	        })();
2916	        self.collect(&num, formed)?;
2917	        self.round_up(&num)
2918	    }
2919	}
