2942	fn publication_h<const L: usize>(
2943	    index: usize,
2944	    meta: &QuantityMeta,
2945	    x: f64,

2942	fn publication_h<const L: usize>(
2943	    index: usize,
2944	    meta: &QuantityMeta,
2945	    x: f64,
2946	    v: &Wide<L>,
2947	    report: &VerificationReport<L>,
2948	    meter: &mut CertificateMeter,
2949	) -> Result<ExactWideSum, AttemptStop>
2950	where
2951	    Wide<L>: SupportedWidth,
2952	{
2953	    let p = i64::from(report.precision);
2954	    let mut h = ExactWideSum::new();
2955	    let formed = (|| {
2956	        h.add_binary64(x, false)?;
2957	        h.add_wide(v, true)?;
2958	        h.make_absolute();
2959	        match meta.kind {
2960	            Kind::Force | Kind::Moment => {
2961	                h.add_wide_scaled(required_error(&report.e_rows, index)?, false, 69, -p)?;
2962	                let w = required_error(&report.w, index)?;
2963	                h.add_wide(w, false)?;
2964	                h.add_wide_scaled(w, false, 1, -p)?;
2965	                h.add_wide(required_error(&report.charge, index)?, false)?;
2966	            }
2967	            Kind::Translation | Kind::Rotation => {
2968	                h.add_wide(required_error(&report.w_plus, index)?, false)?;
2969	                if matches!(meta.id, QuantityId::DisplacementMagnitude(_)) {
2970	                    h.add_wide_scaled(&v.abs(), false, 1, 1 - p)?;
2971	                }
2972	            }
2973	        }
2974	        Ok(())
2975	    })();
2976	    meter.collect(&h, formed)?;
2977	    Ok(h)
2978	}
