2980	/// The protected binary64 allowance, with both branches rounded separately.
2981	fn sharper_binary64(x: f64, scale: f64) -> Result<f64, CertificateIssue> {
2982	    finite_nonnegative(scale)?;
2983	    if !x.is_finite() {
2984	        return Err(CertificateIssue::NonFinite);
2985	    }
2986	    let a0 = f64::from_bits(0x3bf0_0000_0000_0000) * x.abs().max(scale);
2987	    let a1 = a0 * f64::from_bits(0x3ff0_0000_8000_0000);
2988	    let u0 = f64::from_bits(0x3ca0_0000_0000_0000) * x.abs();
2989	    let u1 = u0 + f64::from_bits(1);
2990	    let a2 = a1 + u1;
2991	    for value in [a0, a1, u0, u1, a2] {
2992	        finite_nonnegative(value)?;
2993	    }
2994	    Ok(a2)
2995	}
