2997	fn publication_predicate(
2998	    h: &ExactWideSum,
2999	    row: &PublishedRow,
3000	    scale: f64,
3001	    meter: &mut CertificateMeter,
3002	) -> Result<Option<PublicationPredicate>, AttemptStop> {
3003	    let x = row
3004	        .value
3005	        .value()
3006	        .ok_or_else(|| certificate_error(None, CertificateIssue::RadiusClassMismatch))?;
3007	    if !x.is_finite() {
3008	        return Err(certificate_error(None, CertificateIssue::NonFinite));
3009	    }
3010	    if x.to_bits() == 1u64 << 63 {
3011	        return Err(certificate_error(None, CertificateIssue::NonCanonicalZero));
3012	    }
3013	    finite_nonnegative(scale).map_err(|e| certificate_error(None, e))?;
3014	    let mut compare =
3015	        |predicate, build: &mut dyn FnMut(&mut ExactWideSum) -> Result<(), AttemptStop>| {
3016	            let mut difference = ExactWideSum::new();
3017	            let result = (|| {
3018	                build(&mut difference)?;
3019	                Ok(difference.signum() >= 0)
3020	            })();
3021	            let passed = meter.collect(&difference, result)?;
3022	            Ok::<_, AttemptStop>((!passed).then_some(predicate))
3023	        };
3024	    match row.class {
3025	        RowClass::AbsoluteVerified { bound_bits } => {
3026	            let b = f64::from_bits(bound_bits);
3027	            finite_nonnegative(b).map_err(|e| certificate_error(None, e))?;
3028	            compare(PublicationPredicate::AbsoluteBound, &mut |s| {
3029	                s.add_binary64(b, false)?;
3030	                s.add_scaled(h, true, 1, 0)?;
3031	                Ok(())
3032	            })
3033	        }
3034	        RowClass::RelativeVerified => {
3035	            // Validate the entire finite allowance before its use, even if the
3036	            // earlier public predicate would reject this row.
3037	            let a64 = sharper_binary64(x, scale).map_err(|e| certificate_error(None, e))?;
3038	            if let Some(failed) = compare(PublicationPredicate::PublicRelative, &mut |s| {
3039	                s.add_binary64(x.abs(), false)?;
3040	                s.add_scaled(h, true, 1_000_000_000, 0)?;
3041	                Ok(())
3042	            })? {
3043	                return Ok(Some(failed));
3044	            }
3045	            let m = Wide::<4>::from_f64(x.abs().max(scale))?;
3046	            let abs_x = Wide::<4>::from_f64(x.abs())?;
3047	            if let Some(failed) = compare(PublicationPredicate::SharperExact, &mut |s| {
3048	                s.add_wide_scaled(&m, false, 1, -64)?;
3049	                s.add_wide_scaled(&m, false, 1, -85)?;
3050	                s.add_wide_scaled(&abs_x, false, 1, -53)?;
3051	                s.add_binary64(f64::from_bits(1), false)?;
3052	                s.add_scaled(h, true, 1, 0)?;
3053	                Ok(())
3054	            })? {
3055	                return Ok(Some(failed));
3056	            }
3057	            compare(PublicationPredicate::SharperBinary64, &mut |s| {
3058	                s.add_binary64(a64, false)?;
3059	                s.add_scaled(h, true, 1, 0)?;
3060	                Ok(())
3061	            })
3062	        }
3063	        _ => Err(certificate_error(
3064	            None,
3065	            CertificateIssue::RadiusClassMismatch,
3066	        )),
3067	    }
3068	}
