3092	fn report_shape<const L: usize>(
3093	    prep: &CasePrep,
3094	    candidate_len: usize,
3095	    verification_len: usize,
3096	    candidate_p: u32,
3097	    verification_p: u32,
3098	    report: &VerificationReport<L>,
3099	) -> Result<(), AttemptStop>
3100	where
3101	    Wide<L>: SupportedWidth,
3102	{
3103	    let q = prep.layout.len();
3104	    let b = prep.source.body_count() as usize;
3105	    if verification_p != 2 * candidate_p || report.precision != verification_p {
3106	        return Err(certificate_error(None, CertificateIssue::Precision));
3107	    }
3108	    if candidate_len != q
3109	        || verification_len != q
3110	        || prep.extents.len() != b
3111	        || report.resolution.len() != b
3112	        || report.bodies.len() != b
3113	        || [&report.e_rows, &report.w, &report.charge, &report.w_plus]
3114	            .iter()
3115	            .any(|rows| rows.len() != q)
3116	    {
3117	        return Err(certificate_error(None, CertificateIssue::Shape));
3118	    }
3119	    // A transient canonical layout is released before the publication draft.
3120	    if prep.layout != layout(&prep.source) {
3121	        return Err(certificate_error(None, CertificateIssue::RowIdentity));
3122	    }
3123	    for &extent in &prep.extents {
3124	        finite_nonnegative(extent).map_err(|e| certificate_error(None, e))?;
3125	    }
3126	    for value in report.resolution.iter().flatten() {
3127	        finite_nonnegative(*value).map_err(|e| certificate_error(None, e))?;
3128	    }
3129	    for (index, meta) in prep.layout.iter().enumerate() {
3130	        if meta.body as usize >= b {
3131	            return Err(certificate_error(
3132	                Some(index),
3133	                CertificateIssue::RowIdentity,
3134	            ));
3135	        }
3136	        if meta.input_derived {
3137	            let QuantityId::Displacement(dof) = meta.id else {
3138	                return Err(certificate_error(
3139	                    Some(index),
3140	                    CertificateIssue::RowIdentity,
3141	                ));
3142	            };
3143	            if prep
3144	                .prescribed
3145	                .binary_search_by_key(&dof.global(), |t| t.0)
3146	                .is_err()
3147	            {
3148	                return Err(certificate_error(
3149	                    Some(index),
3150	                    CertificateIssue::MissingField,
3151	                ));
3152	            }
3153	        }
3154	    }
3155	    Ok(())
3156	}
