3158	fn validate_publication_pair(
3159	    prep: &Arc<CasePrep>,
3160	    candidate: &PrecisionState,
3161	    verification: &PrecisionState,
3162	    bound: &BoundVerification,
3163	) -> Result<(), AttemptStop> {
