3165	        return Err(certificate_error(None, CertificateIssue::PairIdentity));
3166	    }
3167	    match (candidate, verification, &bound.report) {
3168	        (PrecisionState::P128(a), PrecisionState::P256(b), VerificationState::V256(r))
3169	            if a.p == 128 && b.p == 256 =>
3170	        {
3171	            report_shape(
3172	                prep,
3173	                a.recovered.values.len(),
3174	                b.recovered.values.len(),
3175	                a.p,
3176	                b.p,
3177	                r,
3178	            )
3179	        }
3180	        (PrecisionState::P256(a), PrecisionState::P512(b), VerificationState::V512(r))
3181	            if a.p == 256 && b.p == 512 =>
3182	        {
3183	            report_shape(
3184	                prep,
3185	                a.recovered.values.len(),
3186	                b.recovered.values.len(),
3187	                a.p,
3188	                b.p,
3189	                r,
3190	            )
3191	        }
3192	        (PrecisionState::P512(a), PrecisionState::P1024(b), VerificationState::V1024(r))
3193	            if a.p == 512 && b.p == 1024 =>
3194	        {
3195	            report_shape(
3196	                prep,
3197	                a.recovered.values.len(),
3198	                b.recovered.values.len(),
3199	                a.p,
3200	                b.p,
3201	                r,
3202	            )
3203	        }
