3208	fn certify_rows<const L: usize>(
3209	    prep: &Arc<CasePrep>,
3210	    precision: u32,
3211	    publication: Publication,
3212	    verification: &[Wide<L>],
3213	    report: &VerificationReport<L>,
3214	    meter: &mut CertificateMeter,
3215	) -> Result<PublicationDecision, AttemptStop>
3216	where
3217	    Wide<L>: SupportedWidth,
3218	{
3219	    let q = prep.layout.len();
3220	    if publication.rows.len() != q || verification.len() != q {
3221	        return Err(certificate_error(None, CertificateIssue::Shape));
3222	    }
3223	    let mut radii = vec![ABSENT_RADIUS_BITS; q].into_boxed_slice();
3224	    for (index, ((row, meta), v)) in publication
3225	        .rows
3226	        .iter()
3227	        .zip(&prep.layout)
3228	        .zip(verification)
3229	        .enumerate()
3230	    {
3231	        if (row.id, row.body, row.kind) != (meta.id, meta.body, meta.kind) {
3232	            return Err(certificate_error(
3233	                Some(index),
3234	                CertificateIssue::RowIdentity,
3235	            ));
3236	        }
3237	        if meta.input_derived {
3238	            if row.class != RowClass::InputDerived {
3239	                return Err(certificate_error(
3240	                    Some(index),
3241	                    CertificateIssue::RadiusClassMismatch,
3242	                ));
3243	            }
3244	            continue;
3245	        }
3246	        let Some(x) = row.value.value() else {
3247	            if row.class != RowClass::Unpublishable {
3248	                return Err(certificate_error(
3249	                    Some(index),
3250	                    CertificateIssue::RadiusClassMismatch,
3251	                ));
3252	            }
3253	            continue;
3254	        };
3255	        if !x.is_finite() {
3256	            return Err(certificate_error(Some(index), CertificateIssue::NonFinite));
3257	        }
3258	        if x.to_bits() == 1u64 << 63 {
3259	            return Err(certificate_error(
3260	                Some(index),
3261	                CertificateIssue::NonCanonicalZero,
3262	            ));
3263	        }
3264	        let scale = publication
3265	            .body_scales
3266	            .get(meta.body as usize * 4 + meta.kind.index())
3267	            .filter(|&&(body, kind, _)| body == meta.body && kind == meta.kind)
3268	            .map(|&(_, _, bits)| f64::from_bits(bits))
3269	            .ok_or_else(|| certificate_error(Some(index), CertificateIssue::Shape))?;
3270	        let h = publication_h(index, meta, x, v, report, meter)?;
3271	        if let Some(predicate) = publication_predicate(&h, row, scale, meter)? {
3272	            return Ok(PublicationDecision::Rejected { index, predicate });
3273	        }
3274	        let radius = meter.round_up(&h)?;
3275	        finite_nonnegative(radius).map_err(|e| certificate_error(Some(index), e))?;
3276	        let ceiling = match row.class {
3277	            RowClass::AbsoluteVerified { bound_bits } => f64::from_bits(bound_bits),
3278	            RowClass::RelativeVerified => {
3279	                sharper_binary64(x, scale).map_err(|e| certificate_error(Some(index), e))?
3280	            }
3281	            _ => {
3282	                return Err(certificate_error(
3283	                    Some(index),
3284	                    CertificateIssue::RadiusClassMismatch,
3285	                ))
3286	            }
3287	        };
3288	        if radius > ceiling {
3289	            return Err(certificate_error(
3290	                Some(index),
3291	                CertificateIssue::RadiusClassMismatch,
3292	            ));
3293	        }
3294	        radii[index] = radius.to_bits();
3295	    }
3296	    meter.checked(Ok(PublicationDecision::Accepted(CertifiedPublication {
3297	        publication,
3298	        radii,
3299	        prep: prep.clone(),
3300	        precision,
3301	    })))
3302	}
