3909	fn terminal(stop: &AttemptStop) -> Result<UnresolvedReason, Refusal> {
3910	    match stop {
3911	        AttemptStop::Budget(scope) => Ok(UnresolvedReason::Budget(*scope)),
3912	        AttemptStop::Span => Ok(UnresolvedReason::ExactSumSpan),
3913	        AttemptStop::Exponent => Ok(UnresolvedReason::ExponentRange),
3914	        AttemptStop::ZeroDiagonal { global_dof } => Ok(UnresolvedReason::ZeroDiagonal {
3915	            global_dof: *global_dof,
3916	        }),
3917	        AttemptStop::Arithmetic(e) => Ok(UnresolvedReason::Arithmetic(*e)),
3918	        AttemptStop::ResolutionScale { body, kind } => {
3919	            Ok(UnresolvedReason::ResolutionScaleUnencodable {
3920	                body: *body,
3921	                kind: *kind,
3922	            })
3923	        }
3924	        AttemptStop::PublicationCertificate { index, issue } => {
3925	            Ok(UnresolvedReason::PublicationCertificate {
3926	                index: *index,
3927	                issue: *issue,
3928	            })
3929	        }
3930	        AttemptStop::NegativeEnergy { i, j } => Err(Refusal::NegativeEnergy { i: *i, j: *j }),
3931	        AttemptStop::Structure => Err(Refusal::Structure),
3932	        other => unreachable!("escalating stop {other:?} is not terminal"),
3933	    }
3934	}
