422	    /// Adds ±other·factor·2^pow2 exactly.
423	    pub(crate) fn add_scaled(
424	        &mut self,
425	        other: &Self,
426	        negate: bool,
427	        factor: u64,
428	        pow2: i64,
429	    ) -> Result<(), SumRefusal> {
430	        if other.empty || factor == 0 {
431	            return Ok(());
432	        }
433	        let lsb = other.anchor + i128::from(pow2);
434	        for (negative, magnitude) in [(false, &other.positive), (true, &other.negative)] {
435	            let mut scaled = [0u64; TERM_LIMBS];
436	            let mut carry = 0u128;
437	            for k in 0..other.used {
438	                let product = u128::from(magnitude[k]) * u128::from(factor) + carry;
439	                scaled[k] = product as u64;
440	                carry = product >> 64;
441	            }
442	            scaled[other.used] = carry as u64;
443	            self.work.term_limbs += other.used as u64;
444	            self.add_raw(negative != negate, &scaled[..=other.used], lsb)?;
445	        }
446	        Ok(())
447	    }
