482	    /// Adds ±a·b exactly, the product of two accumulators' exact values (D1
483	    /// revision 5a.3's exact comparisons of ratios; ROOT's A3-0 ruling Q6): b
484	    /// is netted once, and each of its limbs scales a (`add_scaled`). The
485	    /// product is formed exactly or refused (`Span`, `Exponent`), never
486	    /// truncated; integers only, no allocation.
487	    pub(crate) fn add_product_of(
488	        &mut self,
489	        a: &Self,
490	        b: &mut Self,
491	        negate: bool,
492	    ) -> Result<(), SumRefusal> {
493	        if a.empty || b.empty {
494	            return Ok(());
495	        }
496	        let (negative, magnitude, used) = b.net();
497	        for (k, &limb) in magnitude[..used].iter().enumerate() {
498	            if limb == 0 {
499	                continue;
500	            }
501	            let pow2 =
502	                i64::try_from(b.anchor + 64 * k as i128).map_err(|_| SumRefusal::Exponent)?;
503	            self.add_scaled(a, negate != negative, limb, pow2)?;
504	        }
505	        Ok(())
506	    }
507	
508	    /// The netted exact value: (negative, magnitude, used limbs, anchor).
509	    fn net(&mut self) -> (bool, Magnitude, usize) {
510	        let used = self.used;
511	        self.work.net_limbs += 2 * used as u64;
512	        let (negative, big, small) = match compare(&self.positive[..used], &self.negative[..used]) {
513	            Ordering::Less => (true, &self.negative, &self.positive),
514	            _ => (false, &self.positive, &self.negative),
515	        };
516	        let mut out = [0u64; SUM_LIMBS];
517	        let mut borrow = false;
518	        for i in 0..used {
519	            let (x, b1) = big[i].overflowing_sub(small[i]);
520	            let (y, b2) = x.overflowing_sub(u64::from(borrow));
521	            out[i] = y;
522	            borrow = b1 || b2;
523	        }
524	        debug_assert!(!borrow);
525	        (negative, out, used)
526	    }
