528	    /// The exact value rounded once to the context's precision (nearest, ties
529	    /// to even); an exact zero is +0.
530	    pub(crate) fn round<const L: usize>(
531	        &mut self,
532	        context: &mut WideContext<L>,
533	    ) -> Result<Wide<L>, SumRefusal>
534	    where
535	        Wide<L>: SupportedWidth,
536	    {
537	        if self.empty {
538	            return Ok(context.from_integer(false, &[0], 0)?);
539	        }
540	        let (negative, magnitude, used) = self.net();
541	        let anchor = i64::try_from(self.anchor).map_err(|_| SumRefusal::Exponent)?;
542	        self.work.rounded_limbs += used as u64;
543	        Ok(context.from_integer(negative, &magnitude[..used.max(1)], anchor)?)
544	    }
